export const ProgressView: React.FC = () => {
  const { habits } = useHabitContext();

  // Weekly Data (Bar Chart)
  const weeklyData = useMemo(() => {
    return Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - (6 - i));
      const key = formatDateKey(d);

      const completedCount = habits.reduce((acc, habit) => {
        return acc + (habit.completedDates.includes(key) ? 1 : 0);
      }, 0);

      return {
        day: d.toLocaleDateString('en-US', { weekday: 'short' }),
        completed: completedCount,
      };
    });
  }, [habits]);

  // Monthly Heatmap Data
  const { heatmapData, currentMonthLabel } = useMemo(() => {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth();
    const daysInMonth = getDaysInMonth(year, month);
    const firstDay = getFirstDayOfMonth(year, month);

    // Create grid array
    const grid = [];
    // Padding
    for(let i=0; i<firstDay; i++) grid.push(null);
    // Days
    for(let i=1; i<=daysInMonth; i++) {
        const d = new Date(year, month, i);
        const key = formatDateKey(d);
        const completedCount = habits.reduce((acc, h) => acc + (h.completedDates.includes(key) ? 1 : 0), 0);
        const totalActive = habits.length; // Simplified: assuming habits existed all month
        const intensity = totalActive > 0 ? completedCount / totalActive : 0;

        grid.push({ date: i, intensity, count: completedCount });
    }

    return { 
        heatmapData: grid,
        currentMonthLabel: now.toLocaleString('default', { month: 'long', year: 'numeric' })
    };
  }, [habits]);

  const totalCompletions = habits.reduce((acc, h) => acc + h.completedDates.length, 0);

  // Determine color based on intensity
  const getIntensityColor = (intensity: number) => {
      if (intensity === 0) return 'bg-gray-100 dark:bg-gray-700';
      if (intensity < 0.3) return 'bg-brand-200 dark:bg-brand-900';
      if (intensity < 0.6) return 'bg-brand-400 dark:bg-brand-700';
      return 'bg-brand-600 dark:bg-brand-500';
  };

  return (
    <div className="pb-24 pt-8 px-6 max-w-md mx-auto animate-fade-in">
      <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-6">Your Progress</h1>

