    frequency,
    customDays,
    completedDates: [],
    createdAt: new Date().toISOString()
  };

  return (
    <div className="pb-24 pt-6 px-6 max-w-md mx-auto animate-slide-up">
      <div className="flex justify-between items-center mb-6">
