            <button
              type="button"
              onClick={() => setFrequency('custom')}
              className={`py-3 px-4 rounded-xl text-sm font-medium transition-all ${frequency === 'custom' ? 'bg-brand-500 text-white shadow-lg shadow-brand-500/30' : 'bg-gray-50 dark:bg-gray-800 text-gray-600 dark:text-gray-300'}`}
            >
              Specific Days
            </button>
          </div>

          {frequency === 'custom' && (
            <div className="flex justify-between pt-2">
              {WEEKDAYS.map((day, idx) => {
                const isSelected = customDays.includes(idx);
                return (
                  <button
