import React, { useMemo, useState } from 'react';
import { useHabitContext } from '../context/HabitContext';
import { BarChart, Bar, XAxis, Tooltip, ResponsiveContainer, Cell, CartesianGrid } from 'recharts';
import { formatDateKey, getDaysInMonth, getFirstDayOfMonth, calculateStreak } from '../utils';
import { X, Check, Award, Star, Zap, Medal, Flame } from 'lucide-react';

type TimeRange = '7d' | '30d' | '60d' | '90d';

export const ProgressView: React.FC = () => {
  const { habits } = useHabitContext();
  const [timeRange, setTimeRange] = useState<TimeRange>('7d');
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);

  // Calculate Chart Data based on selected range
  const chartData = useMemo(() => {
    const today = new Date();
    const daysToLookBack = timeRange === '7d' ? 7 : timeRange === '30d' ? 30 : timeRange === '60d' ? 60 : 90;

    const isWeeklyView = daysToLookBack > 30;

    if (isWeeklyView) {
      const weeks = [];
      let currentEnd = new Date(today);
      const numWeeks = Math.ceil(daysToLookBack / 7);

      for (let i = 0; i < numWeeks; i++) {
        const weekStart = new Date(currentEnd);
        weekStart.setDate(currentEnd.getDate() - 6);
        let weeklyTotal = 0;
        for (let d = 0; d < 7; d++) {
          const day = new Date(weekStart);
          day.setDate(weekStart.getDate() + d);
          const key = formatDateKey(day);
          const dailyCount = habits.reduce((acc, h) => acc + (h.completedDates.includes(key) ? 1 : 0), 0);
          weeklyTotal += dailyCount;
        }

        weeks.unshift({
          label: `${weekStart.getDate()}/${weekStart.getMonth()+1}`,
          completed: weeklyTotal,
          fullDate: weekStart
        });
        currentEnd.setDate(currentEnd.getDate() - 7);
      }
      return weeks;
    } else {
      return Array.from({ length: daysToLookBack }, (_, i) => {
        const d = new Date();
        d.setDate(d.getDate() - (daysToLookBack - 1 - i));
        const key = formatDateKey(d);
        const completedCount = habits.reduce((acc, habit) => acc + (habit.completedDates.includes(key) ? 1 : 0), 0);
        return {
          label: d.toLocaleDateString('en-US', { weekday: 'narrow', day: 'numeric' }),
          completed: completedCount,
          fullDate: d
        };
      });
    }
  }, [habits, timeRange]);

  // Monthly Heatmap Data
  const { heatmapData, currentMonthLabel } = useMemo(() => {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth();
    const daysInMonth = getDaysInMonth(year, month);
    const firstDay = getFirstDayOfMonth(year, month);

    const grid = [];
    for(let i=0; i<firstDay; i++) grid.push(null);
    for(let i=1; i<=daysInMonth; i++) {
        const d = new Date(year, month, i);
        const key = formatDateKey(d);
        const completedCount = habits.reduce((acc, h) => acc + (h.completedDates.includes(key) ? 1 : 0), 0);
        const totalActive = habits.length;
        const intensity = totalActive > 0 ? completedCount / totalActive : 0;
        grid.push({ date: i, intensity, count: completedCount, fullDate: d });
    }

    return { 
        heatmapData: grid,
        currentMonthLabel: now.toLocaleString('default', { month: 'long', year: 'numeric' })
    };
  }, [habits]);

  const totalCompletions = habits.reduce((acc, h) => acc + h.completedDates.length, 0);

  const getIntensityColor = (intensity: number) => {
      if (intensity === 0) return 'bg-gray-100 dark:bg-gray-700';
      if (intensity < 0.3) return 'bg-brand-200 dark:bg-brand-900';
      if (intensity < 0.6) return 'bg-brand-400 dark:bg-brand-700';
      return 'bg-brand-600 dark:bg-brand-500';
  };

  const handleDayClick = (dayData: any) => {
    if (!dayData) return;
    const now = new Date();
    // Don't select future dates
    if (dayData.fullDate > now) return;
    setSelectedDate(dayData.fullDate);
  };

  const getSelectedDateStats = () => {
    if (!selectedDate) return null;
    const key = formatDateKey(selectedDate);
    const completed = habits.filter(h => h.completedDates.includes(key));
    const pending = habits.filter(h => !h.completedDates.includes(key));
    return {
      completedHabits: completed,
      missedHabits: pending,
      score: habits.length > 0 ? Math.round((completed.length / habits.length) * 100) : 0
    };
  };

  const selectedStats = getSelectedDateStats();

  // Achievements Logic
  const achievements = [
    { id: 'start', label: 'First Step', desc: 'Complete your first habit', icon: Star, unlocked: totalCompletions > 0, color: 'text-yellow-500 bg-yellow-100 dark:bg-yellow-900/30' },
    { id: 'streak', label: 'On Fire', desc: 'Reach a 3-day streak', icon: Flame, unlocked: habits.some(h => calculateStreak(h) >= 3), color: 'text-orange-500 bg-orange-100 dark:bg-orange-900/30' },
    { id: 'pro', label: 'Dedicated', desc: '20 Total Check-ins', icon: Medal, unlocked: totalCompletions >= 20, color: 'text-blue-500 bg-blue-100 dark:bg-blue-900/30' },
    { id: 'master', label: 'Habit Master', desc: '50 Total Check-ins', icon: Award, unlocked: totalCompletions >= 50, color: 'text-purple-500 bg-purple-100 dark:bg-purple-900/30' },
  ];

  return (
    <div className="pb-24 pt-8 px-6 max-w-md mx-auto animate-fade-in">
      <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-6">Your Progress</h1>

      {/* Summary Cards */}
      <div className="grid grid-cols-2 gap-4 mb-8">
        <div className="bg-blue-500 text-white p-5 rounded-3xl shadow-lg shadow-blue-500/20">
          <div className="text-4xl font-bold mb-1">{totalCompletions}</div>
          <div className="text-blue-100 text-sm font-medium">Total Check-ins</div>
        </div>
        <div className="bg-purple-500 text-white p-5 rounded-3xl shadow-lg shadow-purple-500/20">
          <div className="text-4xl font-bold mb-1">{habits.length}</div>
          <div className="text-purple-100 text-sm font-medium">Active Habits</div>
        </div>
      </div>

      {/* Top Section: Chart OR Day Detail */}
      <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-sm border border-gray-100 dark:border-gray-700 mb-8 min-h-[320px] transition-all">
        {selectedDate && selectedStats ? (
          <div className="animate-fade-in">
            <div className="flex justify-between items-center mb-6">
               <div>
                  <h3 className="text-lg font-bold text-gray-900 dark:text-white">
                    {selectedDate.toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' })}
                  </h3>
                  <p className="text-xs text-gray-500 uppercase tracking-wide">Daily Breakdown</p>
               </div>
               <button onClick={() => setSelectedDate(null)} className="p-2 bg-gray-100 dark:bg-gray-700 rounded-full hover:bg-gray-200 transition-colors">
                  <X size={20} className="text-gray-600 dark:text-gray-300" />
               </button>
            </div>

            <div className="flex items-center gap-6 mb-6">
               <div className="flex flex-col">
                 <span className="text-4xl font-bold text-brand-600">{selectedStats.score}%</span>
                 <span className="text-xs text-gray-400 font-medium">COMPLETED</span>
               </div>
               <div className="h-10 w-[1px] bg-gray-200 dark:bg-gray-700"></div>
               <div className="flex flex-col">
                  <span className="text-xl font-bold text-gray-900 dark:text-white">{selectedStats.completedHabits.length} <span className="text-gray-400 text-sm font-normal">/ {habits.length}</span></span>
                  <span className="text-xs text-gray-400 font-medium">HABITS</span>
               </div>
            </div>

            <div className="space-y-3 max-h-[160px] overflow-y-auto no-scrollbar">
               {selectedStats.completedHabits.length === 0 && selectedStats.missedHabits.length === 0 && (
                 <p className="text-center text-gray-400 text-sm py-4">No habits active on this date.</p>
               )}
               {selectedStats.completedHabits.map(h => (
                  <div key={h.id} className="flex items-center gap-3 p-3 bg-brand-50 dark:bg-brand-900/20 rounded-xl border border-brand-100 dark:border-brand-800">
                     <div className="text-lg">{h.emoji}</div>
                     <span className="font-medium text-gray-900 dark:text-white flex-1 text-sm">{h.name}</span>
                     <div className="bg-brand-500 rounded-full p-0.5"><Check size={12} className="text-white" strokeWidth={3} /></div>
                  </div>
               ))}
               {selectedStats.missedHabits.map(h => (
                  <div key={h.id} className="flex items-center gap-3 p-3 bg-gray-50 dark:bg-gray-700/30 rounded-xl border border-gray-100 dark:border-gray-700 opacity-60">
                     <div className="text-lg grayscale">{h.emoji}</div>
                     <span className="font-medium text-gray-500 dark:text-gray-400 flex-1 text-sm">{h.name}</span>
                     <div className="w-4 h-4 rounded-full border-2 border-gray-300 dark:border-gray-600" />
                  </div>
               ))}
            </div>
          </div>
        ) : (
          <>
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold text-gray-900 dark:text-white">Activity</h3>
              <div className="flex bg-gray-100 dark:bg-gray-700 p-1 rounded-xl">
                {(['7d', '30d', '60d', '90d'] as TimeRange[]).map((range) => (
                  <button
                    key={range}
                    onClick={() => setTimeRange(range)}
                    className={`
                      px-3 py-1 text-xs font-bold rounded-lg transition-all
                      ${timeRange === range 
                        ? 'bg-white dark:bg-gray-600 text-brand-600 dark:text-white shadow-sm' 
                        : 'text-gray-500 dark:text-gray-400 hover:text-gray-700'
                      }
                    `}
                  >
                    {range.toUpperCase()}
                  </button>
                ))}
              </div>
            </div>

            <div className="h-56 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={chartData} margin={{ top: 5, right: 5, left: -20, bottom: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#E5E7EB" opacity={0.3} />
                  <XAxis 
                    dataKey="label" 
                    axisLine={false} 
                    tickLine={false} 
                    tick={{ fill: '#9CA3AF', fontSize: 10 }} 
                    dy={10}
                    interval={timeRange === '7d' ? 0 : 'preserveStartEnd'}
                  />
                  <Tooltip 
                    cursor={{ fill: 'transparent' }}
                    contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }}
                  />
                  <Bar dataKey="completed" radius={[4, 4, 4, 4]} barSize={timeRange === '7d' ? 24 : undefined}>
                    {chartData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill="#3b82f6" fillOpacity={0.8} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
            <p className="text-center text-xs text-gray-400 mt-4">
              Tap a date below to view details
            </p>
          </>
        )}
      </div>

      {/* Monthly Heatmap */}
      <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-sm border border-gray-100 dark:border-gray-700 mb-8">
        <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold text-gray-900 dark:text-white">Monthly Consistency</h3>
            <span className="text-xs text-brand-600 font-medium bg-brand-50 dark:bg-brand-900/30 px-3 py-1 rounded-full">
                {currentMonthLabel}
            </span>
        </div>

        <div className="grid grid-cols-7 gap-2">
            {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map((d, i) => (
                <div key={i} className="text-center text-xs font-bold text-gray-400 mb-1">{d}</div>
            ))}
            {heatmapData.map((day, idx) => {
                if (!day) return <div key={`empty-${idx}`} />;
                const isSelected = selectedDate && formatDateKey(selectedDate) === formatDateKey(day.fullDate);
                const isFuture = day.fullDate > new Date();

                return (
                    <button 
                        key={day.date}
                        onClick={() => handleDayClick(day)}
                        disabled={isFuture}
                        className={`
                          aspect-square rounded-lg flex items-center justify-center text-[10px] font-medium transition-all relative
                          ${getIntensityColor(day.intensity)} 
                          ${day.intensity > 0.5 ? 'text-white' : 'text-gray-500'}
                          ${isSelected ? 'ring-2 ring-brand-600 ring-offset-2 dark:ring-offset-gray-800 z-10' : ''}
                          ${!isFuture ? 'cursor-pointer hover:scale-110 active:scale-95' : 'opacity-30 cursor-default'}
                        `}
                    >
                        {day.date}
                    </button>
                )
            })}
        </div>
      </div>

      {/* Achievements Section */}
      <div className="mb-8">
        <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-4 px-1">Achievements</h3>
        <div className="grid grid-cols-2 gap-3">
           {achievements.map((a) => {
             const Icon = a.icon;
             return (
               <div 
                 key={a.id} 
                 className={`
                   p-4 rounded-2xl border transition-all
                   ${a.unlocked 
                     ? 'bg-white dark:bg-gray-800 border-gray-100 dark:border-gray-700 shadow-sm' 
                     : 'bg-gray-50 dark:bg-gray-800/50 border-transparent opacity-60'
                   }
                 `}
               >
                 <div className="flex items-start justify-between mb-2">
                   <div className={`p-2 rounded-xl ${a.unlocked ? a.color : 'bg-gray-200 dark:bg-gray-700 text-gray-400'}`}>
                     <Icon size={20} />
                   </div>
                   {a.unlocked && <Check size={16} className="text-green-500" />}
                 </div>
                 <div className="font-bold text-sm text-gray-900 dark:text-white">{a.label}</div>
                 <div className="text-xs text-gray-500 dark:text-gray-400">{a.desc}</div>
               </div>
             )
           })}
        </div>
      </div>

      {/* Quote */}
      <div className="bg-gradient-to-r from-orange-400 to-pink-500 p-6 rounded-3xl text-white shadow-lg text-center">
        <h3 className="text-lg font-bold mb-2">Daily Inspiration</h3>
        <p className="opacity-90 text-sm italic">"Consistency is what transforms average into excellence."</p>
      </div>
    </div>
  );
};

export type Frequency = 'daily' | 'weekly' | 'custom';

export type WeekDay = 'Sun' | 'Mon' | 'Tue' | 'Wed' | 'Thu' | 'Fri' | 'Sat';

export interface JournalEntry {
  id: string;
  date: string; // ISO String
  content: string;
}

export interface Habit {
  id: string;
  name: string;
  description: string;
  emoji: string;
  color: string;
  frequency: Frequency;
  customDays: number[]; // 0 = Sunday, 1 = Monday, etc.
  completedDates: string[]; // ISO Date strings "YYYY-MM-DD"
  createdAt: string;

  // New Features
  targetStreak?: number; // Goal: e.g., Reach 30 days
  journal: JournalEntry[];
}

export interface AppSettings {
  darkMode: boolean;
  soundEnabled: boolean;
  animationsEnabled: boolean;
}

export type ViewState = 'today' | 'add' | 'progress' | 'settings' | 'habit-detail';

// For the chart
export interface WeeklyStats {
  day: string;
  completed: number;
  total: number;
}

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { Habit, AppSettings, ViewState, JournalEntry } from '../types';
import { formatDateKey } from '../utils';

interface HabitContextType {
  habits: Habit[];
  settings: AppSettings;
  currentView: ViewState;
  selectedHabitId: string | null;

  addHabit: (habit: Omit<Habit, 'id' | 'createdAt' | 'completedDates' | 'journal'> & { initialNote?: string }) => void;
  updateHabit: (habit: Habit) => void;
  deleteHabit: (id: string) => void;
  toggleCompletion: (id: string, date: Date) => void;
  addJournalEntry: (habitId: string, content: string) => void;

  toggleTheme: () => void;
  toggleSound: () => void;
  toggleAnimations: () => void;
  resetAll: () => void;

  navigate: (view: ViewState, habitId?: string) => void;
}

const HabitContext = createContext<HabitContextType | undefined>(undefined);

export const useHabitContext = () => {
  const context = useContext(HabitContext);
  if (!context) throw new Error('useHabitContext must be used within a HabitProvider');
  return context;
};

// Initial Data for demo purposes if storage is empty
const INITIAL_HABITS: Habit[] = [];
const INITIAL_SETTINGS: AppSettings = {
  darkMode: false,
  soundEnabled: true,
  animationsEnabled: true,
};

export const HabitProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [habits, setHabits] = useState<Habit[]>(() => {
    const saved = localStorage.getItem('habitflow_habits');
    return saved ? JSON.parse(saved) : INITIAL_HABITS;
  });

  const [settings, setSettings] = useState<AppSettings>(() => {
    const saved = localStorage.getItem('habitflow_settings');
    return saved ? JSON.parse(saved) : INITIAL_SETTINGS;
  });

  const [currentView, setCurrentView] = useState<ViewState>('today');
  const [selectedHabitId, setSelectedHabitId] = useState<string | null>(null);

  // Persistence Effects
  useEffect(() => {
    localStorage.setItem('habitflow_habits', JSON.stringify(habits));
  }, [habits]);

  useEffect(() => {
    localStorage.setItem('habitflow_settings', JSON.stringify(settings));
    if (settings.darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [settings]);

  // Actions
  const addHabit = (data: Omit<Habit, 'id' | 'createdAt' | 'completedDates' | 'journal'> & { initialNote?: string }) => {
    const newHabit: Habit = {
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString(),
      completedDates: [],
      name: data.name,
      description: data.description,
      emoji: data.emoji,
      color: data.color,
      frequency: data.frequency,
      customDays: data.customDays,
      targetStreak: data.targetStreak,
      journal: data.initialNote ? [{
        id: Math.random().toString(36).substr(2, 9),
        date: new Date().toISOString(),
        content: data.initialNote
      }] : []
    };
    setHabits((prev) => [...prev, newHabit]);
    navigate('today');
  };

  const updateHabit = (updatedHabit: Habit) => {
    setHabits((prev) => prev.map((h) => (h.id === updatedHabit.id ? updatedHabit : h)));
  };

  const deleteHabit = (id: string) => {
    if(confirm("Are you sure you want to delete this habit?")) {
      setHabits((prev) => prev.filter((h) => h.id !== id));
      navigate('today');
    }
  };

  const toggleCompletion = (id: string, date: Date) => {
    const dateKey = formatDateKey(date);
    setHabits((prev) =>
      prev.map((habit) => {
        if (habit.id !== id) return habit;

        const isCompleted = habit.completedDates.includes(dateKey);
        let newDates;

        if (isCompleted) {
          newDates = habit.completedDates.filter((d) => d !== dateKey);
        } else {
          newDates = [...habit.completedDates, dateKey];
        }

        return { ...habit, completedDates: newDates };
      })
    );
  };

  const addJournalEntry = (habitId: string, content: string) => {
    setHabits((prev) => prev.map(habit => {
      if (habit.id !== habitId) return habit;
      const newEntry: JournalEntry = {
        id: Math.random().toString(36).substr(2, 9),
        date: new Date().toISOString(),
        content
      };
      return { ...habit, journal: [newEntry, ...habit.journal] };
    }));
  };

  const toggleTheme = () => setSettings(s => ({ ...s, darkMode: !s.darkMode }));
  const toggleSound = () => setSettings(s => ({ ...s, soundEnabled: !s.soundEnabled }));
  const toggleAnimations = () => setSettings(s => ({ ...s, animationsEnabled: !s.animationsEnabled }));

  const resetAll = () => {
    if(confirm("Reset all data? This cannot be undone.")) {
      setHabits([]);
      localStorage.removeItem('habitflow_habits');
    }
  };

  const navigate = (view: ViewState, habitId?: string) => {
    setCurrentView(view);
    if (habitId) setSelectedHabitId(habitId);
    else if (view !== 'habit-detail') setSelectedHabitId(null);
  };

  return (
    <HabitContext.Provider
      value={{
        habits,
        settings,
        currentView,
        selectedHabitId,
        addHabit,
        updateHabit,
        deleteHabit,
        toggleCompletion,
        addJournalEntry,
        toggleTheme,
        toggleSound,
        toggleAnimations,
        resetAll,
        navigate,
      }}
    >
      {children}
    </HabitContext.Provider>
  );
};

import React, { useState } from 'react';
import { useHabitContext } from '../context/HabitContext';
import { ALL_COLORS, COMMON_EMOJIS } from '../utils';
import { Frequency } from '../types';
import { X, Check, Sparkles, Target, BookOpen } from 'lucide-react';
import { HabitCard } from '../components/HabitCard';

// Pre-defined suggestions for "Quick Start"
const SUGGESTIONS = [
  { name: 'Drink Water', emoji: '💧', color: '#3b82f6', desc: 'Stay hydrated' },
  { name: 'Read', emoji: '📚', color: '#8b5cf6', desc: 'Read 10 pages' },
  { name: 'Workout', emoji: '🏋️', color: '#ef4444', desc: 'Exercise for 30m' },
  { name: 'Meditate', emoji: '🧘', color: '#10b981', desc: 'Mindfulness' },
  { name: 'Sleep', emoji: '💤', color: '#1e3a8a', desc: '8 hours sleep' },
];

export const AddHabitView: React.FC = () => {
  const { addHabit, navigate } = useHabitContext();

  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [emoji, setEmoji] = useState(COMMON_EMOJIS[0]);
  const [color, setColor] = useState(ALL_COLORS[0]);
  const [frequency, setFrequency] = useState<Frequency>('daily');
  const [customDays, setCustomDays] = useState<number[]>([0,1,2,3,4,5,6]);

  // New Fields
  const [targetStreak, setTargetStreak] = useState<number>(30);
  const [initialNote, setInitialNote] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;

    addHabit({
      name,
      description,
      emoji,
      color,
      frequency,
      customDays: frequency === 'custom' ? customDays : [0,1,2,3,4,5,6],
      targetStreak,
      initialNote: initialNote.trim() || undefined
    });
  };

  const applySuggestion = (s: typeof SUGGESTIONS[0]) => {
    setName(s.name);
    setEmoji(s.emoji);
    setColor(s.color);
    setDescription(s.desc);
  };

  const toggleDay = (dayIndex: number) => {
    setCustomDays(prev => 
      prev.includes(dayIndex) 
        ? prev.filter(d => d !== dayIndex) 
        : [...prev, dayIndex].sort()
    );
  };

  const WEEKDAYS = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];

  // Mock habit for preview
  const previewHabit = {
    id: 'preview',
    name: name || 'Habit Name',
    description: description || 'Your motivation goes here',
    emoji: emoji,
    color: color,
    frequency,
    customDays,
    completedDates: [],
    createdAt: new Date().toISOString(),
    journal: []
  };

  return (
    <div className="pb-24 pt-6 px-6 max-w-md mx-auto animate-slide-up">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold dark:text-white">New Habit</h2>
        <button onClick={() => navigate('today')} className="p-2 bg-gray-100 dark:bg-gray-800 rounded-full text-gray-500">
          <X size={20} />
        </button>
      </div>

      {/* Quick Start Suggestions */}
      <div className="mb-8">
        <div className="flex items-center gap-2 mb-3 text-sm font-bold text-gray-500 uppercase tracking-wide">
          <Sparkles size={14} className="text-yellow-500" />
          Quick Start
        </div>
        <div className="flex gap-3 overflow-x-auto no-scrollbar pb-2">
          {SUGGESTIONS.map((s) => (
            <button
              key={s.name}
              type="button"
              onClick={() => applySuggestion(s)}
              className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-full shadow-sm hover:scale-105 transition-transform flex-shrink-0"
            >
              <span>{s.emoji}</span>
              <span className="text-sm font-medium dark:text-gray-200">{s.name}</span>
            </button>
          ))}
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-8">

        {/* Basic Info Section */}
        <div className="space-y-6">
            {/* Live Preview */}
            <div className="pointer-events-none opacity-90 scale-[0.98] origin-top">
                <HabitCard habit={previewHabit} />
            </div>

            {/* Name Input */}
            <div className="space-y-2">
            <label className="text-sm font-medium text-gray-700 dark:text-gray-300">Habit Name</label>
            <div className="flex gap-3">
                <div className="relative group">
                    <button 
                    type="button"
                    className="w-14 h-14 text-2xl bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-2xl flex items-center justify-center focus:ring-2 focus:ring-brand-500 focus:outline-none"
                    >
                    {emoji}
                    </button>
                    {/* Simple Emoji Picker Popover */}
                    <div className="absolute top-full left-0 mt-2 p-2 bg-white dark:bg-gray-800 shadow-xl rounded-xl z-20 grid grid-cols-4 gap-1 w-48 border border-gray-100 dark:border-gray-700 opacity-0 group-hover:opacity-100 pointer-events-none group-hover:pointer-events-auto transition-opacity">
                    {COMMON_EMOJIS.map(e => (
                        <button 
                        key={e} 
                        type="button" 
                        onClick={() => setEmoji(e)}
                        className="p-1 hover:bg-gray-100 dark:hover:bg-gray-700 rounded text-xl"
                        >
                        {e}
                        </button>
                    ))}
                    </div>
                </div>
                <input
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="e.g., Drink Water"
                className="flex-1 px-4 py-3 bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-2xl focus:ring-2 focus:ring-brand-500 focus:outline-none dark:text-white transition-all"
                required
                />
            </div>
            </div>

            {/* Description / Motivation */}
            <div className="space-y-2">
            <label className="text-sm font-medium text-gray-700 dark:text-gray-300">Motivation</label>
            <input
                type="text"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="Why do you want to build this habit?"
                className="w-full px-4 py-3 bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-2xl focus:ring-2 focus:ring-brand-500 focus:outline-none dark:text-white transition-all"
            />
            </div>

            {/* Color Picker */}
            <div className="space-y-2">
            <label className="text-sm font-medium text-gray-700 dark:text-gray-300">Theme Color</label>
            <div className="flex justify-between gap-2 overflow-x-auto no-scrollbar py-1">
                {ALL_COLORS.map(c => (
                <button
                    key={c}
                    type="button"
                    onClick={() => setColor(c)}
                    className={`w-10 h-10 rounded-full flex-shrink-0 flex items-center justify-center transition-transform ${color === c ? 'scale-110 ring-2 ring-offset-2 ring-gray-300 dark:ring-gray-600' : ''}`}
                    style={{ backgroundColor: c }}
                >
                    {color === c && <Check size={16} className="text-white" strokeWidth={3} />}
                </button>
                ))}
            </div>
            </div>

            {/* Frequency */}
            <div className="space-y-3">
            <label className="text-sm font-medium text-gray-700 dark:text-gray-300">Frequency</label>
            <div className="grid grid-cols-2 gap-3">
                <button
                type="button"
                onClick={() => setFrequency('daily')}
                className={`py-3 px-4 rounded-xl text-sm font-medium transition-all ${frequency === 'daily' ? 'bg-brand-500 text-white shadow-lg shadow-brand-500/30' : 'bg-gray-50 dark:bg-gray-800 text-gray-600 dark:text-gray-300'}`}
                >
                Every Day
                </button>
                <button
                type="button"
                onClick={() => setFrequency('custom')}
                className={`py-3 px-4 rounded-xl text-sm font-medium transition-all ${frequency === 'custom' ? 'bg-brand-500 text-white shadow-lg shadow-brand-500/30' : 'bg-gray-50 dark:bg-gray-800 text-gray-600 dark:text-gray-300'}`}
                >
                Specific Days
                </button>
            </div>

            {frequency === 'custom' && (
                <div className="flex justify-between pt-2">
                {WEEKDAYS.map((day, idx) => {
                    const isSelected = customDays.includes(idx);
                    return (
                    <button
                        key={idx}
                        type="button"
                        onClick={() => toggleDay(idx)}
                        className={`
                        w-10 h-10 rounded-full text-sm font-bold flex items-center justify-center transition-all
                        ${isSelected 
                            ? 'bg-brand-100 text-brand-600 dark:bg-brand-900 dark:text-brand-300' 
                            : 'bg-transparent text-gray-400 border border-gray-200 dark:border-gray-700'
                        }
                        `}
                    >
                        {day}
                    </button>
                    )
                })}
                </div>
            )}
            </div>
        </div>

        <hr className="border-gray-100 dark:border-gray-800" />

        {/* Goal Setting Section */}
        <div className="space-y-6">
           <div className="flex items-center gap-2 text-sm font-bold text-gray-500 uppercase tracking-wide">
             <Target size={14} className="text-red-500" />
             Goals & Targets
           </div>

           <div className="bg-gray-50 dark:bg-gray-800 p-4 rounded-2xl border border-gray-100 dark:border-gray-700">
              <label className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-2 block">
                Target Streak Goal
              </label>
              <div className="flex gap-3">
                 {[7, 30, 60, 100].map(days => (
                   <button
                     key={days}
                     type="button"
                     onClick={() => setTargetStreak(days)}
                     className={`flex-1 py-2 rounded-xl text-sm font-bold transition-all ${targetStreak === days ? 'bg-brand-500 text-white shadow-md' : 'bg-white dark:bg-gray-700 text-gray-500 dark:text-gray-400'}`}
                   >
                     {days} Days
                   </button>
                 ))}
              </div>
              <p className="text-xs text-gray-400 mt-2">
                Challenge yourself to maintain a streak for {targetStreak} consecutive sessions.
              </p>
           </div>
        </div>

        {/* Journal Section */}
        <div className="space-y-6">
           <div className="flex items-center gap-2 text-sm font-bold text-gray-500 uppercase tracking-wide">
             <BookOpen size={14} className="text-purple-500" />
             Initial Journal Entry
           </div>

           <div className="space-y-2">
             <textarea
               value={initialNote}
               onChange={(e) => setInitialNote(e.target.value)}
               placeholder="Write a note to your future self... Why is this habit important to you?"
               className="w-full h-32 px-4 py-3 bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-2xl focus:ring-2 focus:ring-brand-500 focus:outline-none dark:text-white transition-all resize-none font-sans"
             />
             <p className="text-xs text-gray-400 text-right">Markdown supported</p>
           </div>
        </div>

        {/* Submit */}
        <div className="pt-4">
          <button
            type="submit"
            className="w-full py-4 bg-gray-900 dark:bg-white text-white dark:text-gray-900 rounded-2xl font-bold text-lg shadow-xl hover:shadow-2xl hover:scale-[1.02] active:scale-95 transition-all"
          >
            Create Habit
          </button>
        </div>
      </form>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { useHabitContext } from '../context/HabitContext';
import { ArrowLeft, Trash2, Calendar as CalendarIcon, Flame, Trophy, Lock, Book, PenLine, Send } from 'lucide-react';
import { formatDateKey, calculateStreak, getDaysInMonth, getFirstDayOfMonth } from '../utils';

type Tab = 'overview' | 'journal';

export const HabitDetailView: React.FC = () => {
  const { habits, selectedHabitId, navigate, deleteHabit, toggleCompletion, addJournalEntry } = useHabitContext();
  const [activeTab, setActiveTab] = useState<Tab>('overview');
  const [newNote, setNewNote] = useState('');

  const habit = habits.find(h => h.id === selectedHabitId);

  const { calendarData, currentMonthName } = useMemo(() => {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth();
    const daysInMonth = getDaysInMonth(year, month);
    const firstDay = getFirstDayOfMonth(year, month);

    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= daysInMonth; i++) days.push(new Date(year, month, i));

    return { 
      calendarData: days,
      currentMonthName: now.toLocaleString('default', { month: 'long', year: 'numeric' })
    };
  }, []);

  if (!habit) {
    navigate('today');
    return null;
  }

  const streak = calculateStreak(habit);
  const totalCompletions = habit.completedDates.length;
  const todayKey = formatDateKey(new Date());
  const target = habit.targetStreak || 30;
  const progressPercent = Math.min((streak / target) * 100, 100);

  const handleAddNote = () => {
    if (!newNote.trim()) return;
    addJournalEntry(habit.id, newNote);
    setNewNote('');
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 animate-slide-up flex flex-col">
      {/* Header */}
      <div className="bg-white dark:bg-gray-800 pt-6 px-6 rounded-b-[3rem] shadow-sm flex-shrink-0 z-10 relative">
        <div className="flex justify-between items-center mb-6">
          <button onClick={() => navigate('today')} className="p-2 -ml-2 text-gray-600 dark:text-gray-300">
            <ArrowLeft size={24} />
          </button>
          <div className="text-sm font-bold text-gray-400 tracking-wider">DETAILS</div>
          <button 
             onClick={() => deleteHabit(habit.id)}
             className="p-2 text-red-400 hover:text-red-500 transition-colors"
          >
            <Trash2 size={20} />
          </button>
        </div>

        <div className="flex flex-col items-center pb-6">
          <div 
            className="w-20 h-20 rounded-3xl flex items-center justify-center text-4xl mb-3 shadow-inner"
            style={{ backgroundColor: `${habit.color}20` }}
          >
            {habit.emoji}
          </div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white mb-1">{habit.name}</h1>
          <p className="text-gray-500 dark:text-gray-400 text-sm">{habit.description}</p>
        </div>

        {/* Tab Switcher */}
        <div className="flex p-1 bg-gray-100 dark:bg-gray-700 rounded-xl mb-6 relative">
           <button 
             onClick={() => setActiveTab('overview')}
             className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all flex items-center justify-center gap-2 ${activeTab === 'overview' ? 'bg-white dark:bg-gray-600 text-gray-900 dark:text-white shadow-sm' : 'text-gray-500 dark:text-gray-400'}`}
           >
             <CalendarIcon size={16} /> Overview
           </button>
           <button 
             onClick={() => setActiveTab('journal')}
             className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all flex items-center justify-center gap-2 ${activeTab === 'journal' ? 'bg-white dark:bg-gray-600 text-gray-900 dark:text-white shadow-sm' : 'text-gray-500 dark:text-gray-400'}`}
           >
             <Book size={16} /> Journal
           </button>
        </div>
      </div>

      {/* Content Area */}
      <div className="flex-1 p-6 overflow-y-auto no-scrollbar">
        {activeTab === 'overview' ? (
          <div className="animate-fade-in space-y-6">

            {/* Goal Progress Card */}
            <div className="bg-gradient-to-br from-indigo-500 to-purple-600 rounded-3xl p-6 text-white shadow-lg relative overflow-hidden">
               <div className="relative z-10">
                 <div className="flex justify-between items-start mb-4">
                   <div>
                     <p className="text-indigo-100 text-sm font-medium mb-1">Current Streak</p>
                     <h2 className="text-4xl font-bold flex items-center gap-2">
                       {streak} <span className="text-lg opacity-80 font-normal">days</span>
                     </h2>
                   </div>
                   <div className="bg-white/20 p-2 rounded-xl backdrop-blur-sm">
                      <Trophy size={24} className="text-yellow-300" />
                   </div>
                 </div>

                 <div className="mb-2 flex justify-between text-xs font-bold uppercase tracking-wider opacity-80">
                   <span>Goal Progress</span>
                   <span>{streak} / {target}</span>
                 </div>
                 <div className="w-full bg-black/20 h-2 rounded-full overflow-hidden">
                    <div 
                      className="bg-white h-full rounded-full transition-all duration-1000"
                      style={{ width: `${progressPercent}%` }}
                    />
                 </div>
                 {streak >= target && (
                   <div className="mt-4 bg-yellow-400/20 border border-yellow-300/30 rounded-xl p-3 flex items-center gap-3">
                     <Flame className="text-yellow-300" />
                     <p className="text-sm font-medium text-yellow-50">Goal Reached! Amazing work!</p>
                   </div>
                 )}
               </div>

               {/* Background Deco */}
               <div className="absolute -bottom-10 -right-10 w-40 h-40 bg-white/10 rounded-full blur-2xl"></div>
            </div>

            {/* Stats Row */}
            <div className="grid grid-cols-2 gap-4">
               <div className="bg-white dark:bg-gray-800 p-4 rounded-2xl border border-gray-100 dark:border-gray-700">
                  <div className="text-gray-400 text-xs font-bold uppercase mb-1">Total Check-ins</div>
                  <div className="text-2xl font-bold text-gray-900 dark:text-white">{totalCompletions}</div>
               </div>
               <div className="bg-white dark:bg-gray-800 p-4 rounded-2xl border border-gray-100 dark:border-gray-700">
                  <div className="text-gray-400 text-xs font-bold uppercase mb-1">Consistency</div>
                  <div className="text-2xl font-bold text-gray-900 dark:text-white">
                    {Math.round((totalCompletions / (getDaysInMonth(new Date().getFullYear(), new Date().getMonth()) || 1)) * 100)}%
                  </div>
               </div>
            </div>

            {/* Calendar */}
            <div>
                <div className="flex justify-between items-center mb-4">
                  <h3 className="text-lg font-bold text-gray-900 dark:text-white">{currentMonthName}</h3>
                  <span className="text-xs text-gray-400 bg-gray-100 dark:bg-gray-700 px-2 py-1 rounded-lg flex items-center gap-1">
                    <Lock size={10} /> Locked
                  </span>
                </div>
                <div className="bg-white dark:bg-gray-800 rounded-3xl p-5 shadow-sm">
                  <div className="grid grid-cols-7 gap-2 mb-2">
                    {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map((day, i) => (
                      <div key={i} className="text-center text-xs font-bold text-gray-400">{day}</div>
                    ))}
                  </div>
                  <div className="grid grid-cols-7 gap-2">
                    {calendarData.map((date, idx) => {
                      if (!date) return <div key={`empty-${idx}`} />;
                      const key = formatDateKey(date);
                      const isDone = habit.completedDates.includes(key);
                      const isToday = key === todayKey;
                      const canInteract = isToday;
                      return (
                        <button
                          key={key}
                          disabled={!canInteract}
                          onClick={() => toggleCompletion(habit.id, date)}
                          className={`
                            aspect-square rounded-xl flex items-center justify-center text-xs font-medium transition-all relative
                            ${isDone ? 'text-white shadow-sm' : 'text-gray-700 dark:text-gray-300 bg-gray-50 dark:bg-gray-700'}
                            ${isToday && !isDone ? 'ring-2 ring-brand-500 ring-offset-2 dark:ring-offset-gray-800' : ''}
                            ${!canInteract && !isDone ? 'opacity-50 cursor-not-allowed' : ''}
                          `}
                          style={{ backgroundColor: isDone ? habit.color : undefined }}
                        >
                          {date.getDate()}
                        </button>
                      );
                    })}
                  </div>
                </div>
            </div>

          </div>
        ) : (
          <div className="animate-fade-in flex flex-col h-full">
            {/* Add Note Input */}
            <div className="bg-white dark:bg-gray-800 p-4 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 mb-6">
               <div className="flex items-start gap-3">
                  <div className="bg-brand-50 dark:bg-brand-900/20 p-2 rounded-full text-brand-600">
                    <PenLine size={20} />
                  </div>
                  <div className="flex-1">
                    <textarea 
                      value={newNote}
                      onChange={(e) => setNewNote(e.target.value)}
                      placeholder="How did it go today? Any reflections?"
                      className="w-full bg-transparent border-none focus:ring-0 p-0 text-gray-900 dark:text-white placeholder-gray-400 text-sm resize-none h-20"
                    />
                    <div className="flex justify-between items-center mt-2 border-t border-gray-100 dark:border-gray-700 pt-2">
                       <span className="text-xs text-gray-400">Markdown supported</span>
                       <button 
                         onClick={handleAddNote}
                         disabled={!newNote.trim()}
                         className="bg-brand-600 text-white p-2 rounded-xl disabled:opacity-50 hover:bg-brand-700 transition-colors"
                       >
                         <Send size={16} />
                       </button>
                    </div>
                  </div>
               </div>
            </div>

            {/* Journal List */}
            <div className="space-y-4 pb-8">
               {habit.journal && habit.journal.length > 0 ? (
                 habit.journal.map((entry) => (
                   <div key={entry.id} className="flex gap-4">
                      <div className="flex flex-col items-center">
                         <div className="w-2 h-2 rounded-full bg-gray-300 dark:bg-gray-600 mt-2"></div>
                         <div className="w-[1px] bg-gray-200 dark:bg-gray-700 flex-1 my-1"></div>
                      </div>
                      <div className="bg-white dark:bg-gray-800 p-4 rounded-2xl rounded-tl-none shadow-sm flex-1 border border-gray-50 dark:border-gray-700">
                         <div className="text-xs text-gray-400 font-medium mb-1">
                           {new Date(entry.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}
                         </div>
                         <p className="text-gray-700 dark:text-gray-200 text-sm whitespace-pre-line leading-relaxed">
                           {entry.content}
                         </p>
                      </div>
                   </div>
                 ))
               ) : (
                 <div className="text-center py-10 opacity-50">
                    <Book size={48} className="mx-auto mb-3 text-gray-300" />
                    <p className="text-gray-500">No journal entries yet.</p>
                    <p className="text-xs text-gray-400">Reflect on your progress to stay motivated.</p>
                 </div>
               )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export type Frequency = 'daily' | 'weekly' | 'custom';

export type WeekDay = 'Sun' | 'Mon' | 'Tue' | 'Wed' | 'Thu' | 'Fri' | 'Sat';

export interface JournalEntry {
  id: string;
  date: string; // ISO String
  content: string;
}

export interface Habit {
  id: string;
  name: string;
  description: string;
  emoji: string;
  color: string;
  frequency: Frequency;
  customDays: number[]; // 0 = Sunday, 1 = Monday, etc.
  completedDates: string[]; // ISO Date strings "YYYY-MM-DD"
  createdAt: string;

  // New Features
  targetStreak?: number; // Goal: e.g., Reach 30 days
  journal: JournalEntry[];
  archived?: boolean;
}

export interface AppSettings {
  darkMode: boolean;
  soundEnabled: boolean;
  animationsEnabled: boolean;
}

export type ViewState = 'today' | 'add' | 'progress' | 'settings' | 'habit-detail';

// For the chart
export interface WeeklyStats {
  day: string;
  completed: number;
  total: number;
}

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { Habit, AppSettings, ViewState, JournalEntry } from '../types';
import { formatDateKey } from '../utils';

interface HabitContextType {
  habits: Habit[];
  settings: AppSettings;
  currentView: ViewState;
  selectedHabitId: string | null;

  addHabit: (habit: Omit<Habit, 'id' | 'createdAt' | 'completedDates' | 'journal'> & { initialNote?: string }) => void;
  updateHabit: (habit: Habit) => void;
  deleteHabit: (id: string) => void;
  toggleCompletion: (id: string, date: Date) => void;
  toggleArchive: (id: string) => void;
  addJournalEntry: (habitId: string, content: string) => void;

  toggleTheme: () => void;
  toggleSound: () => void;
  toggleAnimations: () => void;
  resetAll: () => void;

  navigate: (view: ViewState, habitId?: string) => void;
}

const HabitContext = createContext<HabitContextType | undefined>(undefined);

export const useHabitContext = () => {
  const context = useContext(HabitContext);
  if (!context) throw new Error('useHabitContext must be used within a HabitProvider');
  return context;
};

// Initial Data for demo purposes if storage is empty
const INITIAL_HABITS: Habit[] = [];
const INITIAL_SETTINGS: AppSettings = {
  darkMode: false,
  soundEnabled: true,
  animationsEnabled: true,
};

export const HabitProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [habits, setHabits] = useState<Habit[]>(() => {
    const saved = localStorage.getItem('habitflow_habits');
    return saved ? JSON.parse(saved) : INITIAL_HABITS;
  });

  const [settings, setSettings] = useState<AppSettings>(() => {
    const saved = localStorage.getItem('habitflow_settings');
    return saved ? JSON.parse(saved) : INITIAL_SETTINGS;
  });

  const [currentView, setCurrentView] = useState<ViewState>('today');
  const [selectedHabitId, setSelectedHabitId] = useState<string | null>(null);

  // Persistence Effects
  useEffect(() => {
    localStorage.setItem('habitflow_habits', JSON.stringify(habits));
  }, [habits]);

  useEffect(() => {
    localStorage.setItem('habitflow_settings', JSON.stringify(settings));
    if (settings.darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [settings]);

  // Actions
  const addHabit = (data: Omit<Habit, 'id' | 'createdAt' | 'completedDates' | 'journal'> & { initialNote?: string }) => {
    const newHabit: Habit = {
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString(),
      completedDates: [],
      name: data.name,
      description: data.description,
      emoji: data.emoji,
      color: data.color,
      frequency: data.frequency,
      customDays: data.customDays,
      targetStreak: data.targetStreak,
      journal: data.initialNote ? [{
        id: Math.random().toString(36).substr(2, 9),
        date: new Date().toISOString(),
        content: data.initialNote
      }] : [],
      archived: false
    };
    setHabits((prev) => [...prev, newHabit]);
    navigate('today');
  };

  const updateHabit = (updatedHabit: Habit) => {
    setHabits((prev) => prev.map((h) => (h.id === updatedHabit.id ? updatedHabit : h)));
  };

  const deleteHabit = (id: string) => {
    if(confirm("Are you sure you want to permanently delete this habit?")) {
      setHabits((prev) => prev.filter((h) => h.id !== id));
      navigate('today');
    }
  };

  const toggleArchive = (id: string) => {
    setHabits((prev) => prev.map((h) => h.id === id ? { ...h, archived: !h.archived } : h));
  };

  const toggleCompletion = (id: string, date: Date) => {
    const dateKey = formatDateKey(date);
    setHabits((prev) =>
      prev.map((habit) => {
        if (habit.id !== id) return habit;

        const isCompleted = habit.completedDates.includes(dateKey);
        let newDates;

        if (isCompleted) {
          newDates = habit.completedDates.filter((d) => d !== dateKey);
        } else {
          newDates = [...habit.completedDates, dateKey];
        }

        return { ...habit, completedDates: newDates };
      })
    );
  };

  const addJournalEntry = (habitId: string, content: string) => {
    setHabits((prev) => prev.map(habit => {
      if (habit.id !== habitId) return habit;
      const newEntry: JournalEntry = {
        id: Math.random().toString(36).substr(2, 9),
        date: new Date().toISOString(),
        content
      };
      return { ...habit, journal: [newEntry, ...habit.journal] };
    }));
  };

  const toggleTheme = () => setSettings(s => ({ ...s, darkMode: !s.darkMode }));
  const toggleSound = () => setSettings(s => ({ ...s, soundEnabled: !s.soundEnabled }));
  const toggleAnimations = () => setSettings(s => ({ ...s, animationsEnabled: !s.animationsEnabled }));

  const resetAll = () => {
    if(confirm("Reset all data? This cannot be undone.")) {
      setHabits([]);
      localStorage.removeItem('habitflow_habits');
    }
  };

  const navigate = (view: ViewState, habitId?: string) => {
    setCurrentView(view);
    if (habitId) setSelectedHabitId(habitId);
    else if (view !== 'habit-detail') setSelectedHabitId(null);
  };

  return (
    <HabitContext.Provider
      value={{
        habits,
        settings,
        currentView,
        selectedHabitId,
        addHabit,
        updateHabit,
        deleteHabit,
        toggleCompletion,
        toggleArchive,
        addJournalEntry,
        toggleTheme,
        toggleSound,
        toggleAnimations,
        resetAll,
        navigate,
      }}
    >
      {children}
    </HabitContext.Provider>
  );
};

import React from 'react';
import { useHabitContext } from '../context/HabitContext';
import { HabitCard } from '../components/HabitCard';
import { isHabitDueOnDate, formatDateKey, calculateUserLevel } from '../utils';
import { Zap } from 'lucide-react';

export const TodayView: React.FC = () => {
  const { habits } = useHabitContext();

  const today = new Date();
  const dateString = today.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
  const greeting = today.getHours() < 12 ? 'Good morning' : today.getHours() < 18 ? 'Good afternoon' : 'Good evening';

  // Filter habits due today AND not archived
  const activeHabits = habits.filter(h => !h.archived);
  const todaysHabits = activeHabits.filter(habit => isHabitDueOnDate(habit, today));

  // Calculate Progress
  const todayKey = formatDateKey(today);
  const completedCount = todaysHabits.filter(h => h.completedDates.includes(todayKey)).length;
  const progress = todaysHabits.length > 0 ? (completedCount / todaysHabits.length) * 100 : 0;

  // Gamification (Total count includes archived ones? Usually yes for history, but let's count all completed)
  const totalAllCompletions = habits.reduce((acc, h) => acc + h.completedDates.length, 0);
  const level = calculateUserLevel(totalAllCompletions);
  const currentLevelProgress = totalAllCompletions % 10;

  return (
    <div className="pb-24 pt-8 px-6 max-w-md mx-auto animate-fade-in">
      {/* Header */}
      <header className="mb-8 flex justify-between items-start">
        <div>
          <p className="text-gray-500 dark:text-gray-400 text-sm font-medium uppercase tracking-wide mb-1">
            {dateString}
          </p>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            {greeting}!
          </h1>
        </div>

        {/* Level Badge */}
        <div className="bg-yellow-100 dark:bg-yellow-900/30 px-3 py-2 rounded-2xl flex flex-col items-end min-w-[80px] border border-yellow-200 dark:border-yellow-800/50">
          <div className="flex items-center gap-1 text-yellow-700 dark:text-yellow-400 font-bold">
            <Zap size={16} className="fill-yellow-500" />
            <span>LVL {level}</span>
          </div>
          <div className="w-full h-1 bg-yellow-200 dark:bg-yellow-900 rounded-full mt-1.5 overflow-hidden">
             <div 
               className="h-full bg-yellow-500 transition-all duration-500" 
               style={{ width: `${(currentLevelProgress / 10) * 100}%` }}
             />
          </div>
        </div>
      </header>

      {/* Daily Progress */}
      {todaysHabits.length > 0 && (
        <div className="mb-8 bg-white dark:bg-gray-800 rounded-2xl p-4 shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="flex justify-between items-end mb-2">
            <span className="text-sm font-medium text-gray-600 dark:text-gray-300">Daily Goal</span>
            <span className="text-2xl font-bold text-brand-600">{Math.round(progress)}%</span>
          </div>
          <div className="h-3 w-full bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden">
            <div 
              className="h-full bg-brand-500 rounded-full transition-all duration-1000 ease-out"
              style={{ width: `${progress}%` }}
            />
          </div>
        </div>
      )}

      {/* Habit List */}
      <div className="space-y-4">
        {todaysHabits.length === 0 ? (
          <div className="text-center py-12 opacity-60">
            <div className="text-6xl mb-4">🌴</div>
            <p className="text-lg font-medium text-gray-900 dark:text-white">No habits for today!</p>
            <p className="text-sm text-gray-500">Enjoy your free time or add a new habit.</p>
          </div>
        ) : (
          todaysHabits.map(habit => (
            <HabitCard key={habit.id} habit={habit} />
          ))
        )}
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { useHabitContext } from '../context/HabitContext';
import { BarChart, Bar, XAxis, Tooltip, ResponsiveContainer, Cell, CartesianGrid } from 'recharts';
import { formatDateKey, getDaysInMonth, getFirstDayOfMonth, calculateStreak } from '../utils';
import { X, Check, Award, Star, Zap, Medal, Flame } from 'lucide-react';

type TimeRange = '7d' | '30d' | '60d' | '90d';

export const ProgressView: React.FC = () => {
  const { habits } = useHabitContext();
  const [timeRange, setTimeRange] = useState<TimeRange>('7d');
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);

  const activeHabits = useMemo(() => habits.filter(h => !h.archived), [habits]);

  // Calculate Chart Data based on selected range
  const chartData = useMemo(() => {
    const today = new Date();
    const daysToLookBack = timeRange === '7d' ? 7 : timeRange === '30d' ? 30 : timeRange === '60d' ? 60 : 90;

    const isWeeklyView = daysToLookBack > 30;

    if (isWeeklyView) {
      const weeks = [];
      let currentEnd = new Date(today);
      const numWeeks = Math.ceil(daysToLookBack / 7);

      for (let i = 0; i < numWeeks; i++) {
        const weekStart = new Date(currentEnd);
        weekStart.setDate(currentEnd.getDate() - 6);
        let weeklyTotal = 0;
        for (let d = 0; d < 7; d++) {
          const day = new Date(weekStart);
          day.setDate(weekStart.getDate() + d);
          const key = formatDateKey(day);
          const dailyCount = activeHabits.reduce((acc, h) => acc + (h.completedDates.includes(key) ? 1 : 0), 0);
          weeklyTotal += dailyCount;
        }

        weeks.unshift({
          label: `${weekStart.getDate()}/${weekStart.getMonth()+1}`,
          completed: weeklyTotal,
          fullDate: weekStart
        });
        currentEnd.setDate(currentEnd.getDate() - 7);
      }
      return weeks;
    } else {
      return Array.from({ length: daysToLookBack }, (_, i) => {
        const d = new Date();
        d.setDate(d.getDate() - (daysToLookBack - 1 - i));
        const key = formatDateKey(d);
        const completedCount = activeHabits.reduce((acc, habit) => acc + (habit.completedDates.includes(key) ? 1 : 0), 0);
        return {
          label: d.toLocaleDateString('en-US', { weekday: 'narrow', day: 'numeric' }),
          completed: completedCount,
          fullDate: d
        };
      });
    }
  }, [activeHabits, timeRange]);

  // Monthly Heatmap Data
  const { heatmapData, currentMonthLabel } = useMemo(() => {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth();
    const daysInMonth = getDaysInMonth(year, month);
    const firstDay = getFirstDayOfMonth(year, month);

    const grid = [];
    for(let i=0; i<firstDay; i++) grid.push(null);
    for(let i=1; i<=daysInMonth; i++) {
        const d = new Date(year, month, i);
        const key = formatDateKey(d);
        const completedCount = activeHabits.reduce((acc, h) => acc + (h.completedDates.includes(key) ? 1 : 0), 0);
        const totalActive = activeHabits.length;
        const intensity = totalActive > 0 ? completedCount / totalActive : 0;
        grid.push({ date: i, intensity, count: completedCount, fullDate: d });
    }

    return { 
        heatmapData: grid,
        currentMonthLabel: now.toLocaleString('default', { month: 'long', year: 'numeric' })
    };
  }, [activeHabits]);

  const totalCompletions = habits.reduce((acc, h) => acc + h.completedDates.length, 0); // Keep global stats including archived

  const getIntensityColor = (intensity: number) => {
      if (intensity === 0) return 'bg-gray-100 dark:bg-gray-700';
      if (intensity < 0.3) return 'bg-brand-200 dark:bg-brand-900';
      if (intensity < 0.6) return 'bg-brand-400 dark:bg-brand-700';
      return 'bg-brand-600 dark:bg-brand-500';
  };

  const handleDayClick = (dayData: any) => {
    if (!dayData) return;
    const now = new Date();
    // Don't select future dates
    if (dayData.fullDate > now) return;
    setSelectedDate(dayData.fullDate);
  };

  const getSelectedDateStats = () => {
    if (!selectedDate) return null;
    const key = formatDateKey(selectedDate);
    const completed = activeHabits.filter(h => h.completedDates.includes(key));
    const pending = activeHabits.filter(h => !h.completedDates.includes(key));
    return {
      completedHabits: completed,
      missedHabits: pending,
      score: activeHabits.length > 0 ? Math.round((completed.length / activeHabits.length) * 100) : 0
    };
  };

  const selectedStats = getSelectedDateStats();

  // Achievements Logic
  const achievements = [
    { id: 'start', label: 'First Step', desc: 'Complete your first habit', icon: Star, unlocked: totalCompletions > 0, color: 'text-yellow-500 bg-yellow-100 dark:bg-yellow-900/30' },
    { id: 'streak', label: 'On Fire', desc: 'Reach a 3-day streak', icon: Flame, unlocked: habits.some(h => calculateStreak(h) >= 3), color: 'text-orange-500 bg-orange-100 dark:bg-orange-900/30' },
    { id: 'pro', label: 'Dedicated', desc: '20 Total Check-ins', icon: Medal, unlocked: totalCompletions >= 20, color: 'text-blue-500 bg-blue-100 dark:bg-blue-900/30' },
    { id: 'master', label: 'Habit Master', desc: '50 Total Check-ins', icon: Award, unlocked: totalCompletions >= 50, color: 'text-purple-500 bg-purple-100 dark:bg-purple-900/30' },
  ];

  return (
    <div className="pb-24 pt-8 px-6 max-w-md mx-auto animate-fade-in">
      <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-6">Your Progress</h1>

      {/* Summary Cards */}
      <div className="grid grid-cols-2 gap-4 mb-8">
        <div className="bg-blue-500 text-white p-5 rounded-3xl shadow-lg shadow-blue-500/20">
          <div className="text-4xl font-bold mb-1">{totalCompletions}</div>
          <div className="text-blue-100 text-sm font-medium">Total Check-ins</div>
        </div>
        <div className="bg-purple-500 text-white p-5 rounded-3xl shadow-lg shadow-purple-500/20">
          <div className="text-4xl font-bold mb-1">{activeHabits.length}</div>
          <div className="text-purple-100 text-sm font-medium">Active Habits</div>
        </div>
      </div>

      {/* Top Section: Chart OR Day Detail */}
      <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-sm border border-gray-100 dark:border-gray-700 mb-8 min-h-[320px] transition-all">
        {selectedDate && selectedStats ? (
          <div className="animate-fade-in">
            <div className="flex justify-between items-center mb-6">
               <div>
                  <h3 className="text-lg font-bold text-gray-900 dark:text-white">
                    {selectedDate.toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' })}
                  </h3>
                  <p className="text-xs text-gray-500 uppercase tracking-wide">Daily Breakdown</p>
               </div>
               <button onClick={() => setSelectedDate(null)} className="p-2 bg-gray-100 dark:bg-gray-700 rounded-full hover:bg-gray-200 transition-colors">
                  <X size={20} className="text-gray-600 dark:text-gray-300" />
               </button>
            </div>

            <div className="flex items-center gap-6 mb-6">
               <div className="flex flex-col">
                 <span className="text-4xl font-bold text-brand-600">{selectedStats.score}%</span>
                 <span className="text-xs text-gray-400 font-medium">COMPLETED</span>
               </div>
               <div className="h-10 w-[1px] bg-gray-200 dark:bg-gray-700"></div>
               <div className="flex flex-col">
                  <span className="text-xl font-bold text-gray-900 dark:text-white">{selectedStats.completedHabits.length} <span className="text-gray-400 text-sm font-normal">/ {activeHabits.length}</span></span>
                  <span className="text-xs text-gray-400 font-medium">HABITS</span>
               </div>
            </div>

            <div className="space-y-3 max-h-[160px] overflow-y-auto no-scrollbar">
               {selectedStats.completedHabits.length === 0 && selectedStats.missedHabits.length === 0 && (
                 <p className="text-center text-gray-400 text-sm py-4">No habits active on this date.</p>
               )}
               {selectedStats.completedHabits.map(h => (
                  <div key={h.id} className="flex items-center gap-3 p-3 bg-brand-50 dark:bg-brand-900/20 rounded-xl border border-brand-100 dark:border-brand-800">
                     <div className="text-lg">{h.emoji}</div>
                     <span className="font-medium text-gray-900 dark:text-white flex-1 text-sm">{h.name}</span>
                     <div className="bg-brand-500 rounded-full p-0.5"><Check size={12} className="text-white" strokeWidth={3} /></div>
                  </div>
               ))}
               {selectedStats.missedHabits.map(h => (
                  <div key={h.id} className="flex items-center gap-3 p-3 bg-gray-50 dark:bg-gray-700/30 rounded-xl border border-gray-100 dark:border-gray-700 opacity-60">
                     <div className="text-lg grayscale">{h.emoji}</div>
                     <span className="font-medium text-gray-500 dark:text-gray-400 flex-1 text-sm">{h.name}</span>
                     <div className="w-4 h-4 rounded-full border-2 border-gray-300 dark:border-gray-600" />
                  </div>
               ))}
            </div>
          </div>
        ) : (
          <>
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold text-gray-900 dark:text-white">Activity</h3>
              <div className="flex bg-gray-100 dark:bg-gray-700 p-1 rounded-xl">
                {(['7d', '30d', '60d', '90d'] as TimeRange[]).map((range) => (
                  <button
                    key={range}
                    onClick={() => setTimeRange(range)}
                    className={`
                      px-3 py-1 text-xs font-bold rounded-lg transition-all
                      ${timeRange === range 
                        ? 'bg-white dark:bg-gray-600 text-brand-600 dark:text-white shadow-sm' 
                        : 'text-gray-500 dark:text-gray-400 hover:text-gray-700'
                      }
                    `}
                  >
                    {range.toUpperCase()}
                  </button>
                ))}
              </div>
            </div>

            <div className="h-56 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={chartData} margin={{ top: 5, right: 5, left: -20, bottom: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#E5E7EB" opacity={0.3} />
                  <XAxis 
                    dataKey="label" 
                    axisLine={false} 
                    tickLine={false} 
                    tick={{ fill: '#9CA3AF', fontSize: 10 }} 
                    dy={10}
                    interval={timeRange === '7d' ? 0 : 'preserveStartEnd'}
                  />
                  <Tooltip 
                    cursor={{ fill: 'transparent' }}
                    contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }}
                  />
                  <Bar dataKey="completed" radius={[4, 4, 4, 4]} barSize={timeRange === '7d' ? 24 : undefined}>
                    {chartData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill="#3b82f6" fillOpacity={0.8} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
            <p className="text-center text-xs text-gray-400 mt-4">
              Tap a date below to view details
            </p>
          </>
        )}
      </div>

      {/* Monthly Heatmap */}
      <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-sm border border-gray-100 dark:border-gray-700 mb-8">
        <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold text-gray-900 dark:text-white">Monthly Consistency</h3>
            <span className="text-xs text-brand-600 font-medium bg-brand-50 dark:bg-brand-900/30 px-3 py-1 rounded-full">
                {currentMonthLabel}
            </span>
        </div>

        <div className="grid grid-cols-7 gap-2">
            {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map((d, i) => (
                <div key={i} className="text-center text-xs font-bold text-gray-400 mb-1">{d}</div>
            ))}
            {heatmapData.map((day, idx) => {
                if (!day) return <div key={`empty-${idx}`} />;
                const isSelected = selectedDate && formatDateKey(selectedDate) === formatDateKey(day.fullDate);
                const isFuture = day.fullDate > new Date();

                return (
                    <button 
                        key={day.date}
                        onClick={() => handleDayClick(day)}
                        disabled={isFuture}
                        className={`
                          aspect-square rounded-lg flex items-center justify-center text-[10px] font-medium transition-all relative
                          ${getIntensityColor(day.intensity)} 
                          ${day.intensity > 0.5 ? 'text-white' : 'text-gray-500'}
                          ${isSelected ? 'ring-2 ring-brand-600 ring-offset-2 dark:ring-offset-gray-800 z-10' : ''}
                          ${!isFuture ? 'cursor-pointer hover:scale-110 active:scale-95' : 'opacity-30 cursor-default'}
                        `}
                    >
                        {day.date}
                    </button>
                )
            })}
        </div>
      </div>

      {/* Achievements Section */}
      <div className="mb-8">
        <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-4 px-1">Achievements</h3>
        <div className="grid grid-cols-2 gap-3">
           {achievements.map((a) => {
             const Icon = a.icon;
             return (
               <div 
                 key={a.id} 
                 className={`
                   p-4 rounded-2xl border transition-all
                   ${a.unlocked 
                     ? 'bg-white dark:bg-gray-800 border-gray-100 dark:border-gray-700 shadow-sm' 
                     : 'bg-gray-50 dark:bg-gray-800/50 border-transparent opacity-60'
                   }
                 `}
               >
                 <div className="flex items-start justify-between mb-2">
                   <div className={`p-2 rounded-xl ${a.unlocked ? a.color : 'bg-gray-200 dark:bg-gray-700 text-gray-400'}`}>
                     <Icon size={20} />
                   </div>
                   {a.unlocked && <Check size={16} className="text-green-500" />}
                 </div>
                 <div className="font-bold text-sm text-gray-900 dark:text-white">{a.label}</div>
                 <div className="text-xs text-gray-500 dark:text-gray-400">{a.desc}</div>
               </div>
             )
           })}
        </div>
      </div>

      {/* Quote */}
      <div className="bg-gradient-to-r from-orange-400 to-pink-500 p-6 rounded-3xl text-white shadow-lg text-center">
        <h3 className="text-lg font-bold mb-2">Daily Inspiration</h3>
        <p className="opacity-90 text-sm italic">"Consistency is what transforms average into excellence."</p>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { useHabitContext } from '../context/HabitContext';
import { ArrowLeft, Trash2, Calendar as CalendarIcon, Flame, Trophy, Lock, Book, PenLine, Send, Archive, RefreshCw } from 'lucide-react';
import { formatDateKey, calculateStreak, getDaysInMonth, getFirstDayOfMonth } from '../utils';

type Tab = 'overview' | 'journal';

export const HabitDetailView: React.FC = () => {
  const { habits, selectedHabitId, navigate, deleteHabit, toggleCompletion, addJournalEntry, toggleArchive } = useHabitContext();
  const [activeTab, setActiveTab] = useState<Tab>('overview');
  const [newNote, setNewNote] = useState('');

  const habit = habits.find(h => h.id === selectedHabitId);

  const { calendarData, currentMonthName } = useMemo(() => {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth();
    const daysInMonth = getDaysInMonth(year, month);
    const firstDay = getFirstDayOfMonth(year, month);

    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= daysInMonth; i++) days.push(new Date(year, month, i));

    return { 
      calendarData: days,
      currentMonthName: now.toLocaleString('default', { month: 'long', year: 'numeric' })
    };
  }, []);

  if (!habit) {
    navigate('today');
    return null;
  }

  const streak = calculateStreak(habit);
  const totalCompletions = habit.completedDates.length;
  const todayKey = formatDateKey(new Date());
  const target = habit.targetStreak || 30;
  const progressPercent = Math.min((streak / target) * 100, 100);

  const handleAddNote = () => {
    if (!newNote.trim()) return;
    addJournalEntry(habit.id, newNote);
    setNewNote('');
  };

  const handleArchive = () => {
    if (!habit.archived) {
      if (confirm("Archive this habit? It will be moved to Settings > Archived Habits.")) {
        toggleArchive(habit.id);
        navigate('today');
      }
    } else {
      toggleArchive(habit.id);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 animate-slide-up flex flex-col">
      {/* Header */}
      <div className="bg-white dark:bg-gray-800 pt-6 px-6 rounded-b-[3rem] shadow-sm flex-shrink-0 z-10 relative">
        <div className="flex justify-between items-center mb-6">
          <button onClick={() => navigate('today')} className="p-2 -ml-2 text-gray-600 dark:text-gray-300">
            <ArrowLeft size={24} />
          </button>
          <div className="text-sm font-bold text-gray-400 tracking-wider">DETAILS</div>
          <div className="flex gap-2">
            <button 
               onClick={handleArchive}
               className="p-2 text-gray-400 hover:text-brand-500 transition-colors"
               title={habit.archived ? "Restore Habit" : "Archive Habit"}
            >
              {habit.archived ? <RefreshCw size={20} /> : <Archive size={20} />}
            </button>
            <button 
               onClick={() => deleteHabit(habit.id)}
               className="p-2 text-red-400 hover:text-red-500 transition-colors"
            >
              <Trash2 size={20} />
            </button>
          </div>
        </div>

        <div className="flex flex-col items-center pb-6">
          <div 
            className="w-20 h-20 rounded-3xl flex items-center justify-center text-4xl mb-3 shadow-inner"
            style={{ backgroundColor: `${habit.color}20` }}
          >
            {habit.emoji}
          </div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white mb-1">{habit.name}</h1>
          <p className="text-gray-500 dark:text-gray-400 text-sm">{habit.description}</p>
          {habit.archived && (
            <span className="mt-2 px-3 py-1 bg-gray-100 dark:bg-gray-700 text-gray-500 text-xs font-bold rounded-full">
              ARCHIVED
            </span>
          )}
        </div>

        {/* Tab Switcher */}
        <div className="flex p-1 bg-gray-100 dark:bg-gray-700 rounded-xl mb-6 relative">
           <button 
             onClick={() => setActiveTab('overview')}
             className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all flex items-center justify-center gap-2 ${activeTab === 'overview' ? 'bg-white dark:bg-gray-600 text-gray-900 dark:text-white shadow-sm' : 'text-gray-500 dark:text-gray-400'}`}
           >
             <CalendarIcon size={16} /> Overview
           </button>
           <button 
             onClick={() => setActiveTab('journal')}
             className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all flex items-center justify-center gap-2 ${activeTab === 'journal' ? 'bg-white dark:bg-gray-600 text-gray-900 dark:text-white shadow-sm' : 'text-gray-500 dark:text-gray-400'}`}
           >
             <Book size={16} /> Journal
           </button>
        </div>
      </div>

      {/* Content Area */}
      <div className="flex-1 p-6 overflow-y-auto no-scrollbar">
        {activeTab === 'overview' ? (
          <div className="animate-fade-in space-y-6">

            {/* Goal Progress Card */}
            <div className="bg-gradient-to-br from-indigo-500 to-purple-600 rounded-3xl p-6 text-white shadow-lg relative overflow-hidden">
               <div className="relative z-10">
                 <div className="flex justify-between items-start mb-4">
                   <div>
                     <p className="text-indigo-100 text-sm font-medium mb-1">Current Streak</p>
                     <h2 className="text-4xl font-bold flex items-center gap-2">
                       {streak} <span className="text-lg opacity-80 font-normal">days</span>
                     </h2>
                   </div>
                   <div className="bg-white/20 p-2 rounded-xl backdrop-blur-sm">
                      <Trophy size={24} className="text-yellow-300" />
                   </div>
                 </div>

                 <div className="mb-2 flex justify-between text-xs font-bold uppercase tracking-wider opacity-80">
                   <span>Goal Progress</span>
                   <span>{streak} / {target}</span>
                 </div>
                 <div className="w-full bg-black/20 h-2 rounded-full overflow-hidden">
                    <div 
                      className="bg-white h-full rounded-full transition-all duration-1000"
                      style={{ width: `${progressPercent}%` }}
                    />
                 </div>
                 {streak >= target && (
                   <div className="mt-4 bg-yellow-400/20 border border-yellow-300/30 rounded-xl p-3 flex items-center gap-3">
                     <Flame className="text-yellow-300" />
                     <p className="text-sm font-medium text-yellow-50">Goal Reached! Amazing work!</p>
                   </div>
                 )}
               </div>

               {/* Background Deco */}
               <div className="absolute -bottom-10 -right-10 w-40 h-40 bg-white/10 rounded-full blur-2xl"></div>
            </div>

            {/* Stats Row */}
            <div className="grid grid-cols-2 gap-4">
               <div className="bg-white dark:bg-gray-800 p-4 rounded-2xl border border-gray-100 dark:border-gray-700">
                  <div className="text-gray-400 text-xs font-bold uppercase mb-1">Total Check-ins</div>
                  <div className="text-2xl font-bold text-gray-900 dark:text-white">{totalCompletions}</div>
               </div>
               <div className="bg-white dark:bg-gray-800 p-4 rounded-2xl border border-gray-100 dark:border-gray-700">
                  <div className="text-gray-400 text-xs font-bold uppercase mb-1">Consistency</div>
                  <div className="text-2xl font-bold text-gray-900 dark:text-white">
                    {Math.round((totalCompletions / (getDaysInMonth(new Date().getFullYear(), new Date().getMonth()) || 1)) * 100)}%
                  </div>
               </div>
            </div>

            {/* Calendar */}
            <div>
                <div className="flex justify-between items-center mb-4">
                  <h3 className="text-lg font-bold text-gray-900 dark:text-white">{currentMonthName}</h3>
                  <span className="text-xs text-gray-400 bg-gray-100 dark:bg-gray-700 px-2 py-1 rounded-lg flex items-center gap-1">
                    <Lock size={10} /> Locked
                  </span>
                </div>
                <div className="bg-white dark:bg-gray-800 rounded-3xl p-5 shadow-sm">
                  <div className="grid grid-cols-7 gap-2 mb-2">
                    {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map((day, i) => (
                      <div key={i} className="text-center text-xs font-bold text-gray-400">{day}</div>
                    ))}
                  </div>
                  <div className="grid grid-cols-7 gap-2">
                    {calendarData.map((date, idx) => {
                      if (!date) return <div key={`empty-${idx}`} />;
                      const key = formatDateKey(date);
                      const isDone = habit.completedDates.includes(key);
                      const isToday = key === todayKey;
                      const canInteract = isToday && !habit.archived;
                      return (
                        <button
                          key={key}
                          disabled={!canInteract}
                          onClick={() => toggleCompletion(habit.id, date)}
                          className={`
                            aspect-square rounded-xl flex items-center justify-center text-xs font-medium transition-all relative
                            ${isDone ? 'text-white shadow-sm' : 'text-gray-700 dark:text-gray-300 bg-gray-50 dark:bg-gray-700'}
                            ${isToday && !isDone ? 'ring-2 ring-brand-500 ring-offset-2 dark:ring-offset-gray-800' : ''}
                            ${!canInteract && !isDone ? 'opacity-50 cursor-not-allowed' : ''}
                          `}
                          style={{ backgroundColor: isDone ? habit.color : undefined }}
                        >
                          {date.getDate()}
                        </button>
                      );
                    })}
                  </div>
                </div>
            </div>

          </div>
        ) : (
          <div className="animate-fade-in flex flex-col h-full">
            {/* Add Note Input */}
            {!habit.archived && (
              <div className="bg-white dark:bg-gray-800 p-4 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 mb-6">
                <div className="flex items-start gap-3">
                    <div className="bg-brand-50 dark:bg-brand-900/20 p-2 rounded-full text-brand-600">
                      <PenLine size={20} />
                    </div>
                    <div className="flex-1">
                      <textarea 
                        value={newNote}
                        onChange={(e) => setNewNote(e.target.value)}
                        placeholder="How did it go today? Any reflections?"
                        className="w-full bg-transparent border-none focus:ring-0 p-0 text-gray-900 dark:text-white placeholder-gray-400 text-sm resize-none h-20"
                      />
                      <div className="flex justify-between items-center mt-2 border-t border-gray-100 dark:border-gray-700 pt-2">
                        <span className="text-xs text-gray-400">Markdown supported</span>
                        <button 
                          onClick={handleAddNote}
                          disabled={!newNote.trim()}
                          className="bg-brand-600 text-white p-2 rounded-xl disabled:opacity-50 hover:bg-brand-700 transition-colors"
                        >
                          <Send size={16} />
                        </button>
                      </div>
                    </div>
                </div>
              </div>
            )}

            {/* Journal List */}
            <div className="space-y-4 pb-8">
               {habit.journal && habit.journal.length > 0 ? (
                 habit.journal.map((entry) => (
                   <div key={entry.id} className="flex gap-4">
                      <div className="flex flex-col items-center">
                         <div className="w-2 h-2 rounded-full bg-gray-300 dark:bg-gray-600 mt-2"></div>
                         <div className="w-[1px] bg-gray-200 dark:bg-gray-700 flex-1 my-1"></div>
                      </div>
                      <div className="bg-white dark:bg-gray-800 p-4 rounded-2xl rounded-tl-none shadow-sm flex-1 border border-gray-50 dark:border-gray-700">
                         <div className="text-xs text-gray-400 font-medium mb-1">
                           {new Date(entry.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}
                         </div>
                         <p className="text-gray-700 dark:text-gray-200 text-sm whitespace-pre-line leading-relaxed">
                           {entry.content}
                         </p>
                      </div>
                   </div>
                 ))
               ) : (
                 <div className="text-center py-10 opacity-50">
                    <Book size={48} className="mx-auto mb-3 text-gray-300" />
                    <p className="text-gray-500">No journal entries yet.</p>
                    <p className="text-xs text-gray-400">Reflect on your progress to stay motivated.</p>
                 </div>
               )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useHabitContext } from '../context/HabitContext';
import { Moon, Sun, Volume2, VolumeX, Zap, RefreshCw, Archive, ChevronDown, ChevronUp, Reply } from 'lucide-react';

export const SettingsView: React.FC = () => {
  const { settings, toggleTheme, toggleSound, toggleAnimations, resetAll, habits, toggleArchive, navigate } = useHabitContext();
  const [showArchived, setShowArchived] = useState(false);

  const archivedHabits = habits.filter(h => h.archived);

  const OptionRow = ({ 
    icon: Icon, 
    label, 
    value, 
    onClick, 
    danger = false 
  }: { 
    icon: any, 
    label: string, 
    value?: boolean, 
    onClick: () => void,
    danger?: boolean
  }) => (
    <button 
      onClick={onClick}
      className="w-full flex items-center justify-between p-4 bg-white dark:bg-gray-800 rounded-2xl border border-gray-100 dark:border-gray-700 mb-3 hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
    >
      <div className="flex items-center gap-4">
        <div className={`p-2 rounded-xl ${danger ? 'bg-red-50 text-red-500' : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300'}`}>
          <Icon size={20} />
        </div>
        <span className={`font-medium ${danger ? 'text-red-500' : 'text-gray-900 dark:text-white'}`}>
          {label}
        </span>
      </div>
      {value !== undefined && (
        <div className={`w-12 h-6 rounded-full p-1 transition-colors ${value ? 'bg-brand-500' : 'bg-gray-300 dark:bg-gray-600'}`}>
          <div className={`w-4 h-4 rounded-full bg-white shadow-sm transition-transform ${value ? 'translate-x-6' : 'translate-x-0'}`} />
        </div>
      )}
    </button>
  );

  return (
    <div className="pb-24 pt-8 px-6 max-w-md mx-auto animate-fade-in">
      <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-8">Settings</h1>

      <div className="mb-8">
        <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-4 ml-1">Preferences</h3>
        <OptionRow 
          icon={settings.darkMode ? Moon : Sun} 
          label="Dark Mode" 
          value={settings.darkMode} 
          onClick={toggleTheme} 
        />
        <OptionRow 
          icon={settings.soundEnabled ? Volume2 : VolumeX} 
          label="Sound Effects" 
          value={settings.soundEnabled} 
          onClick={toggleSound} 
        />
        <OptionRow 
          icon={Zap} 
          label="Animations" 
          value={settings.animationsEnabled} 
          onClick={toggleAnimations} 
        />
      </div>

      <div className="mb-8">
        <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-4 ml-1">Archive</h3>
        <div className="bg-white dark:bg-gray-800 rounded-2xl border border-gray-100 dark:border-gray-700 overflow-hidden">
          <button 
             onClick={() => setShowArchived(!showArchived)}
             className="w-full flex items-center justify-between p-4 hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
          >
             <div className="flex items-center gap-4">
               <div className="p-2 rounded-xl bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300">
                 <Archive size={20} />
               </div>
               <span className="font-medium text-gray-900 dark:text-white">Archived Habits</span>
             </div>
             <div className="flex items-center gap-2">
               <span className="text-xs bg-gray-100 dark:bg-gray-700 px-2 py-1 rounded-full text-gray-500">{archivedHabits.length}</span>
               {showArchived ? <ChevronUp size={20} className="text-gray-400" /> : <ChevronDown size={20} className="text-gray-400" />}
             </div>
          </button>

          {showArchived && (
            <div className="border-t border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
               {archivedHabits.length === 0 ? (
                 <div className="p-6 text-center text-sm text-gray-400">No archived habits.</div>
               ) : (
                 <div className="divide-y divide-gray-100 dark:divide-gray-700">
                   {archivedHabits.map(h => (
                     <div key={h.id} className="flex items-center justify-between p-4">
                        <div 
                          className="flex items-center gap-3 cursor-pointer" 
                          onClick={() => navigate('habit-detail', h.id)}
                        >
                          <span className="text-xl">{h.emoji}</span>
                          <div>
                            <div className="font-medium text-sm text-gray-900 dark:text-white">{h.name}</div>
                            <div className="text-xs text-gray-400">Archived</div>
                          </div>
                        </div>
                        <button 
                          onClick={() => toggleArchive(h.id)}
                          className="p-2 bg-white dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-lg text-brand-600 hover:bg-brand-50 dark:hover:bg-gray-600 transition-colors flex items-center gap-2"
                        >
                          <Reply size={16} />
                          <span className="text-xs font-bold">Restore</span>
                        </button>
                     </div>
                   ))}
                 </div>
               )}
            </div>
          )}
        </div>
      </div>

      <div>
        <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-4 ml-1">Data</h3>
        <OptionRow 
          icon={RefreshCw} 
          label="Reset All Data" 
          onClick={resetAll} 
          danger
        />
      </div>

      <div className="mt-12 text-center">
        <p className="text-xs text-gray-400">HabitFlow v1.1.0</p>
        <p className="text-xs text-gray-300 mt-1">Built with React & Tailwind</p>
      </div>
    </div>
  );
};

import React from 'react';
import { Check, Flame } from 'lucide-react';
import { Habit } from '../types';
import { formatDateKey, isHabitCompleted, calculateStreak } from '../utils';
import { useHabitContext } from '../context/HabitContext';

interface HabitCardProps {
  habit: Habit;
}

export const HabitCard: React.FC<HabitCardProps> = ({ habit }) => {
  const { toggleCompletion, settings, navigate } = useHabitContext();
  const today = new Date();
  const dateKey = formatDateKey(today);
  const isCompleted = isHabitCompleted(habit, dateKey);
  const streak = calculateStreak(habit);

  const handleToggle = (e: React.MouseEvent) => {
    e.stopPropagation();
    toggleCompletion(habit.id, today);
    // Haptic feedback
    if (navigator.vibrate && settings.soundEnabled) { 
       navigator.vibrate(isCompleted ? 10 : 50);
    }
  };

  return (
    <div 
      onClick={() => navigate('habit-detail', habit.id)}
      className={`
        relative group overflow-hidden rounded-3xl p-4 mb-3 transition-all duration-300 ease-out transform 
        hover:scale-[1.02] active:scale-[0.98] cursor-pointer
        border
        ${isCompleted 
          ? 'bg-opacity-10 dark:bg-opacity-10 border-transparent' 
          : 'bg-white dark:bg-gray-800 border-gray-100 dark:border-gray-700 shadow-sm hover:shadow-lg hover:shadow-gray-200/40 dark:hover:shadow-black/20'
        }
      `}
      style={{
        backgroundColor: isCompleted ? `${habit.color}10` : undefined, 
      }}
    >
      <div className="flex items-center justify-between gap-4">
        {/* Left: Content */}
        <div className="flex items-center gap-4 flex-1 min-w-0">
          <div 
            className={`
              flex-shrink-0 flex items-center justify-center w-14 h-14 rounded-2xl text-2xl shadow-sm transition-colors duration-300
              ${isCompleted ? 'bg-white/40 dark:bg-gray-700/40' : 'bg-gray-50 dark:bg-gray-700/50'}
            `}
          >
            {habit.emoji}
          </div>

          <div className="flex flex-col flex-1 min-w-0 py-1">
            <h3 
              className={`
                font-bold text-lg leading-tight truncate transition-all duration-300 
                ${isCompleted ? 'text-gray-400 dark:text-gray-500 line-through decoration-2 decoration-gray-300 dark:decoration-gray-600' : 'text-gray-900 dark:text-white'}
              `}
            >
              {habit.name}
            </h3>
            {habit.description && (
              <p className="text-xs font-medium text-gray-400 dark:text-gray-500 truncate mt-1.5">
                {habit.description}
              </p>
            )}
          </div>
        </div>

        {/* Right: Actions */}
        <div className="flex items-center gap-3">
          {streak > 0 && !isCompleted && (
            <div className="hidden sm:flex items-center gap-1 text-xs font-bold text-orange-500 bg-orange-50 dark:bg-orange-900/30 px-2.5 py-1 rounded-full animate-pulse">
              <Flame size={12} className="fill-orange-500" />
              <span>{streak}</span>
            </div>
          )}

          <button
            onClick={handleToggle}
            className={`
              w-12 h-12 rounded-full flex items-center justify-center transition-all duration-300
              ${isCompleted 
                ? 'text-white shadow-md scale-100' 
                : 'bg-gray-100 dark:bg-gray-700 text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600 hover:text-gray-400'
              }
            `}
            style={{
              backgroundColor: isCompleted ? habit.color : undefined,
              boxShadow: isCompleted ? `0 4px 12px ${habit.color}60` : undefined
            }}
          >
             <Check 
               size={22} 
               strokeWidth={3.5} 
               className={`transition-all duration-300 ${isCompleted ? 'scale-100 opacity-100' : 'scale-50 opacity-0'}`} 
             />
             {!isCompleted && <div className="absolute w-3.5 h-3.5 rounded-full border-[2.5px] border-current opacity-40" />}
          </button>
        </div>
      </div>
    </div>
  );
};

payload.text:
**Expanding the Goal Scope**

I'm currently focused on the `AddHabitView` and expanding the existing goal setting capabilities within the HabitFlow app. I've decided to add a new 'Habit Goals' section after the 'Target Streak Goal' section. In this section, I am planning to implement options for users to specify their habits: 'Complete X times per week'.


**Refining Goal Options**

I'm now honing in on the implementation within `AddHabitView.tsx`. The existing "Goals & Targets" section currently houses only the "Target Streak Goal" which is limited, using predefined buttons. I've decided to refine it. I think the user is requesting more flexible goal-setting options. I see a chance to make `targetStreak` more dynamic. I plan to use input fields to enable users to set custom values for streak goals. I also need to think about adding habit frequency, like "Complete X times per week" to the section as well.


**Adjusting the UI Structure**

I'm now restructuring the UI elements within `AddHabitView.tsx`. My focus is on accommodating the new goal options. I'll maintain the "Target Streak" UI as a core goal, but I'm thinking about making it more customizable or creating a new section. The instructions indicate the new 'Habit Goals' section should be added after 'Target Streak Goal'. This is where I'm concentrating.


**Considering Goal Logic Flexibility**

I'm now contemplating how to integrate the requested "Complete X times per week" feature. It seems the core concept is really about configurable goal logic. The existing `frequency` type doesn't quite fit. I'm noting that the current `weekly` implementation in `types.ts` is a simple `true` return, which isn't useful for a flexible weekly goal. I'll need to figure out how to best integrate a more nuanced weekly frequency.


**Evaluating Visual Requests**

I'm now focusing on the visual requests. Adding a "Habit Goals" section is the immediate task. I'm noting the existing `targetStreak` field within the `Habit` type already addresses the "Achieve Y streak" concept, and I'll consider how best to present that. The main request concerns adding a section. I'm considering if this should be a secondary goal, an enhancement to existing inputs, or a replacement for the streak goal UI.


**Interpreting User Intent**

I'm now assessing the implications of the new "Habit Goals" section request in `AddHabitView`. While "X times per week" sounds like a frequency, my current understanding suggests that the user might desire a more flexible and customizable goal input that compliments or expands on the existing streak functionality. I'm focusing on providing users with a new section with a more granular custom input, rather than a frequency input, for clarity and simplicity.


**Designing Flexible Goals**

I'm now focusing on how to render "Complete X times per week" using the new section. It seems the user wants a flexible way to specify goals. I'm leaning toward implementing a section with a "Goal Type" selection, either "Streak" (mapping to `targetStreak`) or "Weekly Target". If "Weekly Target" is chosen, I'll need an input field for the target number of times, and I need to consider updating the `Habit` type for this new goal property.


**Evaluating Data Structures**

I'm now zeroing in on data structures within `types.ts` to accommodate flexible goals. I'm leaning towards a `goal` object within the `Habit` type that uses a union type to specify either a streak or a weekly target. This should keep the existing `targetStreak` field for backward compatibility, potentially mapping it to the streak goal. I'm aiming for a structure like this:
```typescript
export interface Habit {
  // ...
  goal?: {
    type: 'streak' | 'weekly';
    value: number;
  };
  // ...
}
```

