const HabitContext = createContext<HabitContextType | undefined>(undefined);

export const useHabitContext = () => {
  const context = useContext(HabitContext);
  if (!context) throw new Error('useHabitContext must be used within a HabitProvider');
  return context;
};

// Initial Data for demo purposes if storage is empty
const INITIAL_HABITS: Habit[] = [];
const INITIAL_SETTINGS: AppSettings = {
  darkMode: false,
  soundEnabled: true,
  animationsEnabled: true,
  customLogo: null,
};

export const HabitProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [habits, setHabits] = useState<Habit[]>(() => {
    const saved = localStorage.getItem('habitflow_habits');
    return saved ? JSON.parse(saved) : INITIAL_HABITS;
  });

  const [settings, setSettings] = useState<AppSettings>(() => {
    const saved = localStorage.getItem('habitflow_settings');
    return saved ? JSON.parse(saved) : INITIAL_SETTINGS;
  });

  const [currentView, setCurrentView] = useState<ViewState>('today');
  const [selectedHabitId, setSelectedHabitId] = useState<string | null>(null);

  // Persistence Effects
  useEffect(() => {
    localStorage.setItem('habitflow_habits', JSON.stringify(habits));
  }, [habits]);

  useEffect(() => {
    localStorage.setItem('habitflow_settings', JSON.stringify(settings));
    if (settings.darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [settings]);

  // Actions
  const addHabit = (data: Omit<Habit, 'id' | 'createdAt' | 'completedDates' | 'journal'> & { initialNote?: string }) => {
    // If user set a goal of type streak, we sync it to targetStreak for backward compatibility/UI ease
    const effectiveTargetStreak = data.goal?.type === 'streak' ? data.goal.value : data.targetStreak;

    const newHabit: Habit = {
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString(),
      completedDates: [],
      name: data.name,
      description: data.description,
      emoji: data.emoji,
      color: data.color,
      frequency: data.frequency,
      customDays: data.customDays,
      category: data.category || 'Other',
      targetStreak: effectiveTargetStreak, 
      goal: data.goal,
      journal: data.initialNote ? [{
        id: Math.random().toString(36).substr(2, 9),
        date: new Date().toISOString(),
        content: data.initialNote
      }] : [],
      archived: false
    };
    setHabits((prev) => [...prev, newHabit]);
    navigate('today');
  };

  const updateHabit = (updatedHabit: Habit) => {
    setHabits((prev) => prev.map((h) => (h.id === updatedHabit.id ? updatedHabit : h)));
  };

  const deleteHabit = (id: string) => {
    if(confirm("Are you sure you want to permanently delete this habit?")) {
      setHabits((prev) => prev.filter((h) => h.id !== id));
      navigate('today');
    }
  };

  const toggleArchive = (id: string) => {
    setHabits((prev) => prev.map((h) => h.id === id ? { ...h, archived: !h.archived } : h));
  };

  const toggleCompletion = (id: string, date: Date) => {
    const dateKey = formatDateKey(date);
    setHabits((prev) =>
      prev.map((habit) => {
        if (habit.id !== id) return habit;

        const isCompleted = habit.completedDates.includes(dateKey);
        let newDates;

        if (isCompleted) {
          newDates = habit.completedDates.filter((d) => d !== dateKey);
        } else {
          newDates = [...habit.completedDates, dateKey];
        }

        return { ...habit, completedDates: newDates };
      })
    );
  };

  const addJournalEntry = (habitId: string, content: string) => {
    setHabits((prev) => prev.map(habit => {
      if (habit.id !== habitId) return habit;
      const newEntry: JournalEntry = {
        id: Math.random().toString(36).substr(2, 9),
        date: new Date().toISOString(),
        content
      };
      return { ...habit, journal: [newEntry, ...habit.journal] };
    }));
  };

  const toggleTheme = () => setSettings(s => ({ ...s, darkMode: !s.darkMode }));
  const toggleSound = () => setSettings(s => ({ ...s, soundEnabled: !s.soundEnabled }));
  const toggleAnimations = () => setSettings(s => ({ ...s, animationsEnabled: !s.animationsEnabled }));
  const setCustomLogo = (logo: string | null) => setSettings(s => ({ ...s, customLogo: logo }));

  const resetAll = () => {
    if(confirm("Reset all data? This cannot be undone.")) {
      setHabits([]);
      localStorage.removeItem('habitflow_habits');
    }
  };

  const navigate = (view: ViewState, habitId?: string) => {
    setCurrentView(view);
    if (habitId) setSelectedHabitId(habitId);
    else if (view !== 'habit-detail') setSelectedHabitId(null);
  };

  return (
    <HabitContext.Provider
      value={{
        habits,
        settings,
        currentView,
        selectedHabitId,
        addHabit,
        updateHabit,
        deleteHabit,
        toggleCompletion,
        toggleArchive,
        addJournalEntry,
        toggleTheme,
        toggleSound,
        toggleAnimations,
        setCustomLogo,
        resetAll,
        navigate,
      }}
    >
      {children}
    </HabitContext.Provider>
  );
};

import React from 'react';
import { Check, Flame } from 'lucide-react';
import { Habit } from '../types.ts';
import { formatDateKey, isHabitCompleted, calculateStreak } from '../utils.ts';
import { useHabitContext } from '../context/HabitContext.tsx';

interface HabitCardProps {
  habit: Habit;
}

export const HabitCard: React.FC<HabitCardProps> = ({ habit }) => {
  const { toggleCompletion, settings, navigate } = useHabitContext();
  const today = new Date();
  const dateKey = formatDateKey(today);
  const isCompleted = isHabitCompleted(habit, dateKey);
  const streak = calculateStreak(habit);

  const handleToggle = (e: React.MouseEvent) => {
    e.stopPropagation();
    toggleCompletion(habit.id, today);
    // Haptic feedback
    if (navigator.vibrate && settings.soundEnabled) { 
       navigator.vibrate(isCompleted ? 10 : 50);
    }
  };

  return (
    <div 
      onClick={() => navigate('habit-detail', habit.id)}
      className={`
        relative group overflow-hidden rounded-3xl p-4 mb-3 transition-all duration-300 ease-out transform 
        hover:scale-[1.02] active:scale-[0.98] cursor-pointer
        border
        ${isCompleted 
          ? 'bg-opacity-10 dark:bg-opacity-10 border-transparent' 
          : 'bg-white dark:bg-gray-800 border-gray-100 dark:border-gray-700 shadow-sm hover:shadow-lg hover:shadow-gray-200/40 dark:hover:shadow-black/20'
        }
      `}
      style={{
        backgroundColor: isCompleted ? `${habit.color}10` : undefined, 
      }}
    >
      <div className="flex items-center justify-between gap-4">
        {/* Left: Content */}
        <div className="flex items-center gap-4 flex-1 min-w-0">
          <div 
            className={`
              flex-shrink-0 flex items-center justify-center w-14 h-14 rounded-2xl text-2xl shadow-sm transition-colors duration-300
              ${isCompleted ? 'bg-white/40 dark:bg-gray-700/40' : 'bg-gray-50 dark:bg-gray-700/50'}
            `}
          >
            {habit.emoji}
          </div>

          <div className="flex flex-col flex-1 min-w-0 py-1">
            <h3 
              className={`
                font-bold text-lg leading-tight truncate transition-all duration-300 
                ${isCompleted ? 'text-gray-400 dark:text-gray-500 line-through decoration-2 decoration-gray-300 dark:decoration-gray-600' : 'text-gray-900 dark:text-white'}
              `}
            >
              {habit.name}
            </h3>
            {habit.description && (
              <p className="text-xs font-medium text-gray-400 dark:text-gray-500 truncate mt-1.5">
                {habit.description}
              </p>
            )}
          </div>
        </div>

        {/* Right: Actions */}
        <div className="flex items-center gap-3">
          {streak > 0 && !isCompleted && (
            <div className="hidden sm:flex items-center gap-1 text-xs font-bold text-orange-500 bg-orange-50 dark:bg-orange-900/30 px-2.5 py-1 rounded-full animate-pulse">
              <Flame size={12} className="fill-orange-500" />
              <span>{streak}</span>
            </div>
          )}

          <button
            onClick={handleToggle}
            className={`
              w-12 h-12 rounded-full flex items-center justify-center transition-all duration-300
              ${isCompleted 
                ? 'text-white shadow-md scale-100' 
                : 'bg-gray-100 dark:bg-gray-700 text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600 hover:text-gray-400'
              }
            `}
            style={{
              backgroundColor: isCompleted ? habit.color : undefined,
              boxShadow: isCompleted ? `0 4px 12px ${habit.color}60` : undefined
            }}
          >
             <Check 
               size={22} 
               strokeWidth={3.5} 
               className={`transition-all duration-300 ${isCompleted ? 'scale-100 opacity-100' : 'scale-50 opacity-0'}`} 
             />
             {!isCompleted && <div className="absolute w-3.5 h-3.5 rounded-full border-[2.5px] border-current opacity-40" />}
          </button>
        </div>
      </div>
    </div>
  );
};

